// Помощник для растеризации SVG в PNG Data URL
const rasterizeSvg = (svgString: string): Promise<{ data: string, width: number, height: number } | null> => {
    if (!svgString || !svgString.trim()) return Promise.resolve(null);
    
    return new Promise((resolve) => {
        const img = new Image();
        // Обработка unicode символов в SVG для кодирования в Base64
        const svg64 = btoa(unescape(encodeURIComponent(svgString)));
        const b64Start = 'data:image/svg+xml;base64,';
        const image64 = b64Start + svg64;

        img.onload = () => {
            const canvas = document.createElement('canvas');
            // Коэффициент масштабирования для лучшего качества печати (например, коэффициент 3 или 4)
            const scale = 4; 
            canvas.width = img.width * scale;
            canvas.height = img.height * scale;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.scale(scale, scale);
                ctx.drawImage(img, 0, 0);
                resolve({ 
                    data: canvas.toDataURL('image/png'), 
                    width: img.width, 
                    height: img.height 
                });
            } else {
                resolve(null);
            }
        };
        img.onerror = (e) => {
            console.error("Failed to render SVG", e);
            resolve(null);
        };
        img.src = image64;
    });
};

export const generateMortgagePDF = async (
    input: CalculationInput, 
    result: CalculationResult,
    propertyInfo?: PropertyInfo
): Promise<void> => {
    const doc = new jsPDF();

    // Параллельная загрузка шрифтов и SVG
    const fontPromise = (async () => {
        try {
            const fontUrl = 'https://cdnjs.cloudflare.com/ajax/libs/pdfmake/0.1.66/fonts/Roboto/Roboto-Regular.ttf';
            const response = await fetch(fontUrl);
            if (!response.ok) throw new Error("Failed to load font");
            const blob = await response.blob();
            return new Promise<string>((resolve) => {
                const reader = new FileReader();
                reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
                reader.readAsDataURL(blob);
            });
        } catch (error) {
            console.error("Font loading error", error);
            return null;
        }
    })();

    const [fontBase64, headerLogo, footerGraphics] = await Promise.all([
        fontPromise,
        rasterizeSvg(HEADER_LOGO_SVG),
        rasterizeSvg(FOOTER_GRAPHICS_SVG)
    ]);

    if (fontBase64) {
        doc.addFileToVFS('Roboto-Regular.ttf', fontBase64);
        doc.addFont('Roboto-Regular.ttf', 'Roboto', 'normal');
        doc.setFont('Roboto');
    }

    generatePdfContent(doc, input, result, headerLogo, footerGraphics, propertyInfo);
    
    const dateStr = new Date().toLocaleDateString('ru-RU');
    doc.save(`Расчет ${dateStr}.pdf`);
};

const generatePdfContent = (
    doc: jsPDF, 
    input: CalculationInput, 
    result: CalculationResult,
    headerLogo: { data: string, width: number, height: number } | null,
    footerGraphics: { data: string, width: number, height: number } | null,
    propertyInfo?: PropertyInfo
) => {
    // Фирменные цвета
    const SPK_GREEN: [number, number, number] = [0, 141, 70]; // #008D46 approx
    const SPK_BLUE: [number, number, number] = [0, 159, 227]; // #009FE3 approx
    const SPK_DARK_CYAN: [number, number, number] = [0, 95, 115]; // #005F73 approx for footer shapes
    const TEXT_DARK: [number, number, number] = [60, 60, 60];

    // Помощник для расчета производных данных
    const minIncome = result.monthlyPayment * 2;
    
    // Группировка графика по календарным годам
    const scheduleByYear: { [year: number]: MonthlyPayment[] } = {};
    result.schedule.forEach(item => {
        const year = item.paymentDate.getFullYear();
        if (!scheduleByYear[year]) scheduleByYear[year] = [];
        scheduleByYear[year].push(item);
    });

    const pageWidth = doc.internal.pageSize.width;
    const pageHeight = doc.internal.pageSize.height;
    const margin = 14;

    // Расчет высоты футера для отступов
    let footerHeight = 15; // значение по умолчанию
    if (footerGraphics) {
        footerHeight = (footerGraphics.height / footerGraphics.width) * pageWidth;
    }

    // Определение нижнего отступа контента (высота футера + отступ)
    const contentBottomMargin = footerHeight + 10; 

    // --- Шапка ---
    const drawHeader = (doc: jsPDF) => {
        if (headerLogo) {
            // Рендеринг SVG шапки
            // Уменьшенный размер: было 15, стало 9мм (логотип меньше по запросу)
            const targetH = 9; 
            const targetW = (headerLogo.width / headerLogo.height) * targetH;
            doc.addImage(headerLogo.data, 'PNG', 14, 8, targetW, targetH);
        } else {
            // Имитация логотипа "СПК"
            // Зеленая часть
            doc.setFillColor(SPK_GREEN[0], SPK_GREEN[1], SPK_GREEN[2]);
            doc.rect(14, 8, 12, 8, 'F'); 
            // Синяя часть (треугольник)
            doc.setFillColor(SPK_BLUE[0], SPK_BLUE[1], SPK_BLUE[2]);
            doc.triangle(14, 16, 26, 16, 14, 22, 'F'); 
            
            // Заголовок "СТРОЙПАНЕЛЬКОМПЛЕКТ"
            doc.setTextColor(SPK_BLUE[0], SPK_BLUE[1], SPK_BLUE[2]);
            doc.setFontSize(14);
            doc.setFont("Roboto", "normal"); 
            doc.text("СТРОЙПАНЕЛЬКОМПЛЕКТ", 29, 14); 

            // Подзаголовок "НЕДВИЖИМОСТЬ"
            doc.setFillColor(SPK_GREEN[0], SPK_GREEN[1], SPK_GREEN[2]);
            doc.rect(29, 16, 68, 6, 'F');
            doc.setTextColor(255, 255, 255);
            doc.setFontSize(9);
            doc.text("Н Е Д В И Ж И М О С Т Ь", 31, 20.5);
        }

        // Контактная информация (Справа) - Всегда видима
        doc.setTextColor(0, 0, 0);
        doc.setFontSize(9);
        const rightX = pageWidth - 14;
        
        doc.text("Офис продаж", rightX, 10, { align: 'right' });
        doc.text("«СтройПанельКомплект»", rightX, 14, { align: 'right' });
        doc.text("ул. Монастырская, 12 Б, г. Пермь, 614000", rightX, 18, { align: 'right' });
        doc.text("тел.: +7 (342) 217 93 03", rightX, 22, { align: 'right' });
        doc.text("www.spk.perm.ru", rightX, 26, { align: 'right' });
    };

    // --- Футер ---
    const drawFooter = (doc: jsPDF) => {
        if (footerGraphics) {
            // Рендеринг SVG футера
            // Масштабируем под ширину страницы, сохраняя пропорции
            // footerHeight рассчитан выше
            doc.addImage(footerGraphics.data, 'PNG', 0, pageHeight - footerHeight, pageWidth, footerHeight);
        } else {
            // Синяя полоса
            doc.setFillColor(SPK_BLUE[0], SPK_BLUE[1], SPK_BLUE[2]);
            doc.rect(0, pageHeight - 15, pageWidth, 15, 'F');

            // Геометрические фигуры справа (Трапеции/Треугольники)
            doc.setFillColor(SPK_DARK_CYAN[0], SPK_DARK_CYAN[1], SPK_DARK_CYAN[2]);
            // Абстрактная фигура
            doc.triangle(pageWidth - 60, pageHeight - 15, pageWidth, pageHeight - 15, pageWidth, pageHeight - 5, 'F');
            doc.triangle(pageWidth - 60, pageHeight - 15, pageWidth, pageHeight - 5, pageWidth - 30, pageHeight, 'F'); 
            
            // Наложение зеленой фигуры
            doc.setFillColor(106, 168, 79); // Светло-зеленый
            doc.triangle(pageWidth - 40, pageHeight, pageWidth, pageHeight, pageWidth, pageHeight - 8, 'F');

            // Текст ссылки
            doc.setTextColor(255, 255, 255);
            doc.setFontSize(10);
            doc.text("www.spk.perm.ru", 14, pageHeight - 6);
        }
    };

    // Начальная отрисовка Шапки/Футера
    drawHeader(doc);
    drawFooter(doc);

    // --- Основной контент ---
    let currentY = 40;

    // --- Карточка объекта недвижимости ---
    if (propertyInfo) {
        const cardHeight = 90; // Увеличенная высота для большого изображения
        const contentWidth = pageWidth - (margin * 2);
        
        // Фон карточки (Светло-серый)
        doc.setFillColor(248, 250, 252); // slate-50
        doc.setDrawColor(226, 232, 240); // slate-200
        doc.roundedRect(margin, currentY, contentWidth, cardHeight, 3, 3, 'FD');

        const innerMargin = 6;
        const startX = margin + innerMargin;
        const startY = currentY + innerMargin;
        
        // Заголовок "Объект"
        doc.setFontSize(16);
        doc.setTextColor(TEXT_DARK[0], TEXT_DARK[1], TEXT_DARK[2]);
        doc.setFont('Roboto', 'normal'); // Жирный шрифт недоступен в простой конфигурации, используем размер
        doc.text("Объект", startX, startY + 5);
        
        // Адрес
        doc.setFontSize(12);
        doc.setTextColor(30, 41, 59); // slate-800
        doc.text(propertyInfo.address, startX, startY + 14);

        // Изображение планировки (Справа)
        const imageWidth = 90; // Значительно увеличенная ширина
        const imageHeight = 78; // Увеличенная высота под размер карточки
        const imageX = margin + contentWidth - innerMargin - imageWidth;
        const imageY = startY; // выравнивание по верху
        
        // Отрисовка рамки/фона контейнера изображения
        doc.setDrawColor(203, 213, 225); // slate-300
        doc.setFillColor(255, 255, 255);
        doc.rect(imageX, imageY, imageWidth, imageHeight, 'FD');
        
        if (propertyInfo.imageUrl) {
            try {
                 // Попытка рендеринга предоставленного изображения
                 doc.addImage(propertyInfo.imageUrl, 'JPEG', imageX + 1, imageY + 1, imageWidth - 2, imageHeight - 2);
            } catch (e) {
                 // Фолбек, если изображение недоступно
                 doc.setFontSize(9);
                 doc.setTextColor(148, 163, 184);
                 doc.text("Планировка", imageX + (imageWidth / 2), imageY + (imageHeight / 2), { align: 'center' });
            }
        } else {
             // Текст-заполнитель
             doc.setFontSize(9);
             doc.setTextColor(148, 163, 184);
             doc.text("Планировка", imageX + (imageWidth / 2), imageY + (imageHeight / 2), { align: 'center' });
        }

        // Детали объекта (Слева, под адресом)
        const detailsStartY = startY + 28;
        const colWidth = 40;
        const rowGap = 10;
        
        doc.setFontSize(10);
        
        const drawDetail = (label: string, value: string, x: number, y: number) => {
             doc.setTextColor(100, 116, 139); // цвет метки (slate-500)
             doc.text(label, x, y);
             doc.setTextColor(15, 23, 42); // цвет значения (slate-900)
             doc.text(value, x, y + 5);
        };

        // Строка 1
        drawDetail("Площадь", propertyInfo.area, startX, detailsStartY);
        drawDetail("Комнат", propertyInfo.rooms, startX + colWidth, detailsStartY);
        
        // Строка 2
        drawDetail("Отделка", propertyInfo.finish, startX, detailsStartY + rowGap);
        drawDetail("Этаж", propertyInfo.floor, startX + colWidth, detailsStartY + rowGap);

        // --- Секция менеджера (Добавлено по запросу) ---
        const managerStartY = startY + cardHeight + 8; // Позиция под карточкой
        
        doc.setFontSize(12);
        doc.setTextColor(TEXT_DARK[0], TEXT_DARK[1], TEXT_DARK[2]);
        doc.text("Ваш менеджер", margin, managerStartY);
        
        doc.setFontSize(10);
        
        const managerName = propertyInfo.managerName || "";
        const managerPhone = propertyInfo.managerPhone || "";
        
        // Имя
        doc.setTextColor(100, 116, 139); // цвет метки
        doc.text("Имя:", margin, managerStartY + 6);
        doc.setTextColor(30, 41, 59); // цвет значения
        doc.text(managerName, margin + 25, managerStartY + 6);

        // Телефон
        doc.setTextColor(100, 116, 139); // цвет метки
        doc.text("Телефон:", margin, managerStartY + 11);
        doc.setTextColor(30, 41, 59); // цвет значения
        doc.text(managerPhone, margin + 25, managerStartY + 11);

        // Обновление Y для следующей секции (Карточка + Инфо менеджера + Отступ)
        currentY += cardHeight + 35; 
    } else {
        // Отступ по умолчанию, если нет карточки объекта
        currentY += 10;
    }

    // Заголовок
    doc.setFontSize(16);
    doc.setTextColor(TEXT_DARK[0], TEXT_DARK[1], TEXT_DARK[2]);
    doc.text("Результаты расчета ипотеки", 14, currentY);
    
    currentY += 10;

    // Блок параметров
    doc.setFontSize(11);
    doc.setTextColor(0, 0, 0);
    
    // Левая колонка ввода
    doc.text(`Стоимость недвижимости: ${formatCurrency(input.propertyValue)}`, 14, currentY);
    doc.text(`Сумма кредита: ${formatCurrency(result.loanAmount)}`, 14, currentY + 6);
    doc.text(`Процентная ставка: ${input.interestRate}%`, 14, currentY + 12);
    doc.text(`Срок кредита: ${input.years} лет`, 14, currentY + 18);
    doc.text(`Дата выдачи: ${formatDate(new Date(input.startDate))}`, 14, currentY + 24);

    // Правая колонка сводки - Вывод простым текстом
    const rightColX = 110;
    
    // Заголовок сводки
    doc.text("Итоговые показатели", rightColX, currentY);
    
    // Строки данных сводки - ПРЯМОЙ вывод ТЕКСТА вместо autoTable
    const summaryStartY = currentY;
    const lineHeight = 6;
    
    // Строка 1
    doc.text(`Ежемесячный платеж: ${formatCurrency(result.monthlyPayment)}`, rightColX, summaryStartY + lineHeight);
    
    // Строка 2
    doc.text(`Начисленные проценты: ${formatCurrency(result.totalInterest)}`, rightColX, summaryStartY + (lineHeight * 2));
    
    // Строка 3
    doc.text(`Общая сумма выплат: ${formatCurrency(result.totalPayment)}`, rightColX, summaryStartY + (lineHeight * 3));
    
    // Строка 4
    doc.text(`Необходимый доход: ${formatCurrency(minIncome)}`, rightColX, summaryStartY + (lineHeight * 4));

    // Расчет начальной позиции для таблицы графика
    const tableStartY = Math.max(summaryStartY + (lineHeight * 4) + 15, currentY + 35);

    doc.setFontSize(14);
    doc.setTextColor(TEXT_DARK[0], TEXT_DARK[1], TEXT_DARK[2]);
    doc.text("График платежей", 14, tableStartY - 5);
    
    // Контент таблицы
    const pdfBody: any[] = [];
    
    Object.keys(scheduleByYear).sort().forEach(yearStr => {
        const year = Number(yearStr);
        const payments = scheduleByYear[year];
        
        // Заголовок года
        pdfBody.push([{ 
            content: `${year} год`, 
            colSpan: 6, 
            styles: { 
                fillColor: [241, 245, 249], 
                textColor: [71, 85, 105],
                font: 'Roboto',
                fontStyle: 'normal' 
            } 
        }]);

        payments.forEach(p => {
             pdfBody.push([
                p.monthIndex,
                formatDate(p.paymentDate),
                formatCurrency(p.payment),
                formatCurrency(p.principalPart),
                formatCurrency(p.interestPart),
                formatCurrency(p.remainingBalance)
             ]);
        });
        
        const yearPrincipal = payments.reduce((acc, curr) => acc + curr.principalPart, 0);
        const yearInterest = payments.reduce((acc, curr) => acc + curr.interestPart, 0);
        const yearTotal = payments.reduce((acc, curr) => acc + curr.payment, 0);
        
        // Итоги года
        pdfBody.push([{ 
            content: `Выплачено за год: ${formatCurrency(yearTotal)} (Долг: ${formatCurrency(yearPrincipal)}, %: ${formatCurrency(yearInterest)})`, 
            colSpan: 6, 
            styles: { 
                halign: 'right', 
                textColor: [100, 116, 139],
                font: 'Roboto',
                fontStyle: 'normal'
            } 
        }]);
    });

    autoTable(doc, {
      startY: tableStartY,
      head: [['№', 'Дата', 'Платеж', 'Осн. долг', 'Проценты', 'Остаток']],
      body: pdfBody,
      theme: 'grid',
      // Принудительный нормальный стиль шрифта везде
      headStyles: { fillColor: SPK_GREEN, textColor: 255, font: 'Roboto', fontStyle: 'normal' },
      styles: { font: 'Roboto', fontStyle: 'normal', fontSize: 9, cellPadding: 2 },
      columnStyles: {
          0: { cellWidth: 15, halign: 'center' },
          5: { textColor: [100, 100, 100] }
      },
      didDrawPage: function (data) {
          drawHeader(doc);
          drawFooter(doc);
      },
      margin: { top: 35, bottom: contentBottomMargin }
    });
};
